function TropicalPower(A, k):
    P <- TropicalIdentity(n)        # 0 on diagonal, +inf elsewhere
    B <- A
    while k > 0:
        if k is odd:
            P <- TropMatMul(P, B)
        B <- TropMatMul(B, B)
        k <- floor(k / 2)
    return P

function TDLPAttack(A, B, v):
    lamA <- Residual(A, v)[0]      # eigenvalue of A on eigenvector v
    lamB <- Residual(B, v)[0]      # eigenvalue of B = A^{(x)k}
    if lamA == 0:
        return FAIL                # boundary: eigenzero_no_leak, no leak
    return round(lamB / lamA)
